--
-- Table structure for table `bots`
--

DROP TABLE IF EXISTS `bots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bots` (
  `user` varchar(20) NOT NULL DEFAULT '',
  `level` tinyint unsigned NOT NULL DEFAULT '0',
  `sign` varchar(4) NOT NULL DEFAULT 'none',
  `s1` smallint NOT NULL DEFAULT '0',
  `s2` smallint NOT NULL DEFAULT '0',
  `s3` smallint NOT NULL DEFAULT '0',
  `s4` smallint NOT NULL DEFAULT '0',
  `s5` smallint NOT NULL DEFAULT '0',
  `s6` smallint NOT NULL DEFAULT '0',
  `kb` int NOT NULL DEFAULT '0',
  `mf1` int NOT NULL DEFAULT '0',
  `mf2` int NOT NULL DEFAULT '0',
  `mf3` int NOT NULL DEFAULT '0',
  `mf4` int NOT NULL DEFAULT '0',
  `mf5` int NOT NULL DEFAULT '0',
  `udmin` int NOT NULL DEFAULT '0',
  `udmax` int NOT NULL DEFAULT '0',
  `sm4` smallint NOT NULL DEFAULT '0',
  `hp` int NOT NULL DEFAULT '0',
  `ma` int NOT NULL DEFAULT '0',
  `id` int NOT NULL DEFAULT '0',
  `pol` varchar(6) NOT NULL DEFAULT '',
  `obr` varchar(20) NOT NULL DEFAULT '',
  `wears` tinytext NOT NULL,
  `rank_i` float NOT NULL DEFAULT '0',
  `id_skin` tinyint unsigned NOT NULL DEFAULT '0',
  `where_ap` tinyint unsigned NOT NULL DEFAULT '0',
  `droptype` tinyint unsigned NOT NULL DEFAULT '0',
  `dropvalue` bigint NOT NULL DEFAULT '0',
  `dropfrequency` tinyint unsigned NOT NULL DEFAULT '0',
  `magic_resistance` tinyint unsigned NOT NULL DEFAULT '0',
  `special` smallint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  KEY `id_2` (`id`),
  KEY `user` (`user`),
  KEY `special` (`special`)
) ENGINE=MyISAM DEFAULT CHARSET=cp1251;
/*!40101 SET character_set_client = @saved_cs_client */;

