INSERT INTO `fight_log` VALUES ('23:18','Бой между <img src=images/signs/none.gif><font class=bnick color=#087C20>Варвар</font>[<font class=lvl>19</font>] ,<img src=images/signs/none.gif><font class=bnick color=#087C20>Акуллекс</font>[<font class=lvl>23</font>] ,<img src=images/signs/none.gif><font class=bnick color=#087C20>Акуллекс</font>[<font class=lvl>23</font>] и <img src=images/signs/c2.gif><font class=bnick color=#0052A6>BETEPAH</font>[<font class=lvl>19</font>] .(Нападение существ)',11,1314375485.27),('23:18','<font class=bnick color=#087C20>Акуллекс</font>[23] <b>погиб</b>.%<font class=bnick color=#087C20>Варвар</font>[19] <b>погиб</b>.% <font class=bnick color=#0052A6>BETEPAH</font> обыскал существо. Результаты: <b>Ничего не найдено.</b>% <font class=bnick color=#0052A6>BETEPAH</font> обыскал существо. Результаты: <b>Ничего не найдено.</b>%<font class=bnick color=#0052A6>BETEPAH</font>[19] <b>заблокировал</b> <font class=timef>«оглушающий удар в голову»</font>. &nbsp;%<img src=images/arena/bits/t/a7.gif height=16 title=Точный><font class=bnick color=#0052A6>BETEPAH</font>[19] ,<font color=green>нанося яростный удар</font>, поразил <font class=bnick color=#087C20>Варвар</font>[19] на <b class=user>-1545</b> <font class=timef>«простой удар в грудь»</font><font class=hp_in_f>[0/747]</font>. &nbsp;<img src=images/arena/bits/s/a11.gif height=16 title=Сокрушительный><font class=bnick color=#0052A6>BETEPAH</font>[19] ,<font color=green>нанося яростный удар</font>, поразил <font class=bnick color=#087C20>Акуллекс</font>[23] на	<font class=bnick color=#CC0000><b>-2288</b></font> <font class=timef>«cокрушительный простой удар по ногам»</font><font class=hp_in_f>[0/1204]</font>. &nbsp',11,1314375506.26),('23:18','<img src=images/arena/bits/d/a7.gif height=16 title=Уворот><font class=bnick color=#087C20>Акуллекс</font>[23] пытался поразить соперника, но <font class=bnick color=#0052A6>BETEPAH</font>[19] <b>увернулся</b> от <font class=timef>«оглушающий удар в грудь»</font>. &nbsp;<img src=images/arena/bits/t/a3.gif height=16 title=Точный><font class=bnick color=#087C20>Акуллекс</font>[23]  поразил <font class=bnick color=#0052A6>BETEPAH</font>[19] на <b class=user>-201</b> <font class=timef>«оглушающий удар по животу»</font><font class=hp_in_f>[2399/2600]</font>. &nbsp;',11,1314375514.09),('23:18','<font class=bnick color=#087C20>Акуллекс</font>[23] <b>погиб</b>.% <font class=bnick color=#0052A6>BETEPAH</font> обыскал существо. Результаты: <b>Ничего не найдено.</b>%<font class=bnick color=#0052A6>BETEPAH</font>[19] <b>заблокировал</b> <font class=timef>«оглушающий удар в голову»</font>. &nbsp;<font class=bnick color=#0052A6>BETEPAH</font>[19] <b>заблокировал</b> <font class=timef>«оглушающий удар в грудь»</font>. &nbsp;%<img src=images/arena/bits/s/a1.gif height=16 title=Сокрушительный><font class=bnick color=#0052A6>BETEPAH</font>[19]  поразил <font class=bnick color=#087C20>Акуллекс</font>[23] на	<font class=bnick color=#CC0000><b>-1186</b></font> <font class=timef>«cокрушительный простой удар в грудь»</font><font class=hp_in_f>[18/1204]</font>. &nbsp;<img src=images/arena/bits/s/a7.gif height=16 title=Сокрушительный><font class=bnick color=#0052A6>BETEPAH</font>[19]  поразил <font class=bnick color=#087C20>Акуллекс</font>[23] на	<font class=bnick color=#CC0000><b>-1166</b></font> <font class=timef>«cокрушительный простой удар по ногам»</font><font class=hp_in_f>[0/1204]</font>. &nbsp',11,1314375518.29),('23:22','Бой между <img src=images/signs/none.gif><font class=bnick color=#087C20>Варвар</font>[<font class=lvl>18</font>] ,<img src=images/signs/none.gif><font class=bnick color=#087C20>Варвар</font>[<font class=lvl>19</font>] и <img src=images/signs/c2.gif><font class=bnick color=#0052A6>BETEPAH</font>[<font class=lvl>19</font>] .(Нападение существа)',12,1314375725.91),('23:24','<font class=bnick color=#087C20>Варвар</font>[18] <b>погиб</b>.% <font class=bnick color=#0052A6>BETEPAH</font> обыскал существо. Результаты: <b>Нич