--
-- Table structure for table `fights`
--

DROP TABLE IF EXISTS `fights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fights` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` text CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL,
  `namevs` text CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL,
  `all` longtext CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL,
  `travm` smallint NOT NULL DEFAULT '0',
  `oruj` smallint NOT NULL DEFAULT '0',
  `type` varchar(10) NOT NULL DEFAULT 'notf',
  `turn` longtext NOT NULL,
  `ltime` int NOT NULL DEFAULT '0',
  `timeout` int NOT NULL DEFAULT '0',
  `stones` int NOT NULL DEFAULT '0',
  `courses` smallint NOT NULL DEFAULT '0',
  `bplace` tinyint NOT NULL DEFAULT '1',
  `result` text NOT NULL,
  `players` tinyint unsigned NOT NULL DEFAULT '0',
  `nowhom` tinyint unsigned NOT NULL DEFAULT '0',
  `nowhomvote` text NOT NULL,
  `maxx` smallint NOT NULL DEFAULT '0',
  `maxy` smallint NOT NULL DEFAULT '0',
  `nobots` tinyint unsigned NOT NULL DEFAULT '0',
  `closed` tinyint unsigned NOT NULL DEFAULT '0',
  `special` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_2` (`id`),
  KEY `id` (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=141 DEFAULT CHARSET=cp1251;
/*!40101 SET character_set_client = @saved_cs_client */;

