INSERT INTO `tips` VALUES (1,'Поощрения!!!','Поощрения в клане будут раздаваться: \r\n\r\n\r\n\r\n',2),(2,'Поощрения!!!','1. За пополнения казны стоящими вещами\r\n\r\n\r\n\r\n',2),(3,'Поощрения!!!','2. За достойный вклад в развитие клана; \r\n',2),(4,'Поощрения!!!','3. За большой вклад в копилку ЛН и БР; \r\n\r\n\r\n',2),(5,'Поощрения!!!','4. В честь праздников соклановцев.\r\n',2),(6,'Поощрения!!!','5. Новым членам клана.\r\n',2),(7,'Поощрения!!!','Вид поощрения - Благословение на час!!!',2),(8,'налоги','еженедельно 100 монет -7 лэвл\r\n',2),(9,'налоги','+50 монет к ста за каждый след лэвл\r\n\r\n',2),(10,'налоги','12 – 350 13 – 400 14 – 450 15 – 500 ',2),(11,'налоги','16–550 17–600 18–650 19–700 20–750\r\n',2),(12,'Зелье титановой кожи','Астрагал,Лавр.Лист,Мускат.Орех,Корица',2),(13,'Зелье великана','Фенхель,Айва,Шпинат,Сатанинский гриб',2),(14,'Зелье горца','Лук,Облепиха,Чеснок,Алоэ',2),(15,'Зелье невидимости','Груздь чёрный, Чёрный перец\r\n\r\n',2),(16,'Зелье невидимости','Тысячелистник, Рядовка серая',2),(17,'Зелье атлета','Крапива,Орегано',2),(18,'Зелье восстановления','Базелик,Инжир,Айва',2),(19,'ВАЖНО!!! ВСЕМ!!!','для продажи в казну шмот не кидайте\r\n\r\n',2),(20,'ВАЖНО!!! ВСЕМ!!!','продается он только в полцены',2),(21,'ВАЖНО!!! ВСЕМ!!!','передавайте лучше экономистам',2),(22,'ВАЖНО!!! ВСЕМ!!!','продавайте через них',2);
/*!40000 ALTER TABLE `tips` ENABLE KEYS */;
UNLOCK TABLES;

