CREATE TABLE `u_blasts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `id_in_w` bigint unsigned NOT NULL DEFAULT '0',
  `name` varchar(255) NOT NULL DEFAULT '',
  `image` varchar(30) NOT NULL DEFAULT '',
  `tlevel` tinyint unsigned NOT NULL DEFAULT '0',
  `ts6` smallint unsigned NOT NULL DEFAULT '0',
  `tm1` smallint unsigned NOT NULL DEFAULT '0',
  `tm2` smallint unsigned NOT NULL DEFAULT '0',
  `tm3` smallint unsigned NOT NULL DEFAULT '0',
  `tm4` smallint unsigned NOT NULL DEFAULT '0',
  `tm5` smallint unsigned NOT NULL DEFAULT '0',
  `manacost` smallint unsigned NOT NULL DEFAULT '0',
  `colldown` bigint unsigned NOT NULL DEFAULT '0',
  `turn_colldown` smallint unsigned NOT NULL DEFAULT '0',
  `type` tinyint unsigned NOT NULL DEFAULT '0',
  `price` bigint unsigned NOT NULL DEFAULT '0',
  `dprice` bigint unsigned NOT NULL DEFAULT '0',
  `udmin` smallint unsigned NOT NULL DEFAULT '0',
  `udmax` smallint unsigned NOT NULL DEFAULT '0',
  `where_buy` tinyint unsigned NOT NULL DEFAULT '0',
  `aura_id` bigint unsigned NOT NULL DEFAULT '0',
  `targets` tinyint unsigned NOT NULL DEFAULT '0',
  `describe` varchar(255) NOT NULL DEFAULT '',
  `uidp` bigint unsigned NOT NULL DEFAULT '0',
  `cur_colldown` bigint unsigned NOT NULL DEFAULT '0',
  `cur_turn_colldown` smallint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_in_w` (`id_in_w`,`uidp`),
  KEY `uidp` (`uidp`)
) ENGINE=MyISAM AUTO_INCREMENT=686 DEFAULT CHARSET=cp1251;
