INSERT INTO `weather` VALUES (1,'Ясно','Растения прорастают с нормальной скоростью.;Регенерация +1%;Возможна засуха(Только летом);\r\n',5,10800),(2,'Дождь','Все растения растут в 2 раза быстрее;\r\nРегерация маны +1%;Регенерация жизни -1%;Скорость перемещения +5 сек;',5,900),(3,'Ливень','Растения начинают гнить;Регенерация жизни -5%;Усталость за переход +2;Время перемещения +12 сек;Рыбалка +50;',5,600),(4,'Ветер','Скорость перемещения -3 сек;Точность -20%;',5,10800),(5,'Шторм','Рыбалка -50%;Перемещение на лодках недоступно;',5,1800),(6,'Туман','Регенерация маны +5%;Скорость перемещения -50%;Точность -50%;Растения растут в 3 раза быстрее!;',5,10800),(7,'Град','Рыбалка -80%;Алхимия -80%;Регенерация жизни -60%;Скорость передвижения +60 сек;Возможно получение лёгкой травмы!;',1,600),(8,'Снегопад','Регенерация жизни -10%;Перемещение +5 сек;',1,1800);
